// src/pages/CurrentIssue.js
import React, { useEffect, useState } from "react";
import { papersAPI } from "../services/api";
import { PageHero, PaperCard, Spinner, EmptyState, Card } from "../components/common";

const CurrentIssue = () => {
  const [papers, setPapers] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    papersAPI.getPublished()
      .then((res) => {
        const all = res.papers || [];
        // Get latest volume/issue
        const sorted = [...all].sort((a, b) =>
          (b.volume || 0) - (a.volume || 0) || (b.issue || 0) - (a.issue || 0)
        );
        if (sorted.length > 0) {
          const latestVol = sorted[0].volume;
          const latestIssue = sorted[0].issue;
          setPapers(all.filter((p) => p.volume === latestVol && p.issue === latestIssue));
        } else {
          // Show all published if no volume/issue set
          setPapers(all);
        }
      })
      .catch(() => setPapers([]))
      .finally(() => setLoading(false));
  }, []);

  const vol = papers[0]?.volume;
  const iss = papers[0]?.issue;

  return (
    <div>
      <PageHero
        title="Current Issue"
        subtitle={vol && iss ? `Volume ${vol}, Issue ${iss}` : "Latest published articles"}
        breadcrumb="Home / Current Issue"
      />
      <div className="max-w-5xl mx-auto px-4 py-10">
        {vol && iss && (
          <Card className="p-4 mb-6 bg-blue-50 border-blue-200">
            <p className="text-sm text-blue-800">
              <strong>Volume {vol}, Issue {iss}</strong> — {papers.length} article{papers.length !== 1 ? "s" : ""}
            </p>
          </Card>
        )}

        {loading ? (
          <Spinner center />
        ) : papers.length > 0 ? (
          <div className="space-y-3">
            {papers.map((p) => <PaperCard key={p.id} paper={p} />)}
          </div>
        ) : (
          <EmptyState
            title="No current issue yet"
            message="The editorial team has not published any papers yet. Check back soon!"
          />
        )}
      </div>
    </div>
  );
};

export default CurrentIssue;
